import("regexp";"sort";"strings")
func LabelOverlay(s string)(string,bool){p:=strings.Split(s,";");if len(p)!=2{return "",false};d:=map[string]string{};k:=regexp.MustCompile(`^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$`);valid:=func(v string)bool{if v==""{return false};for _,c:=range []byte(v){if c<32||c>126||c==','||c==';'{return false}};return true};if p[0]!=""{for _,r:=range strings.Split(p[0],","){q:=strings.SplitN(r,"=",2);if len(q)!=2||!k.MatchString(q[0])||!valid(q[1]){return "",false};if _,ok:=d[q[0]];ok{return "",false};d[q[0]]=q[1]}};if p[1]!=""{for _,op:=range strings.Split(p[1],","){if strings.HasPrefix(op,"set:"){q:=strings.SplitN(op[4:],"=",2);if len(q)!=2||!k.MatchString(q[0])||!valid(q[1]){return "",false};d[q[0]]=q[1]}else if strings.HasPrefix(op,"unset:")&&k.MatchString(op[6:]){delete(d,op[6:])}else{return "",false}}};keys:=[]string{};for x:=range d{keys=append(keys,x)};sort.Strings(keys);o:=[]string{};for _,x:=range keys{o=append(o,x+"="+d[x])};return strings.Join(o,","),true}
